def ext(url,label):
 return f'<a href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer">{label} ↗<span class="sr-only"> (external website, opens in a new tab)</span></a>'
def ref(n):return f'<sup class="ref"><a href="#source-{n}" aria-label="Source {n}">[{n}]</a></sup>'
def table(head,rows):return '<div class="table-wrap" role="region" aria-label="Comparison; scroll horizontally on small screens" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def shell(route,title,desc,h1,answer,parts,sources,script=False,recs=False):
 nav=navigation(route)
 body=''.join(f'<section id="{i}"><h2>{h}</h2>{text}</section>' for i,h,text in parts)
 source='<section class="sources" id="sources"><h2>Sources &amp; verification</h2><ol>'+''.join(f'<li id="source-{i}">{ext(u,l)} — {d}</li>' for i,(u,l,d) in enumerate(sources,1))+'</ol><a class="back" href="#guide">Back to guide ↑</a></section>'
 related='<section><h2>Related choices</h2><div class="related"><a href="/vampire-survivors/">Official browser demo</a><a href="/vampire-survivors/co-op/">Co-op compatibility</a><a href="/games-like-vampire-survivors/">Choose a browser survivor</a></div></section>'
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="https://megabonk.org{route}"><meta property="og:type" content="article"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="https://megabonk.org{route}"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/pokebonk/site.css"><link rel="stylesheet" href="/assets/guide-article-layout.css"><link rel="stylesheet" href="/assets/vampire-survivors/site.css">{AD}{'<script defer src="/assets/vampire-survivors/compatibility.js"></script>' if script else ''}</head><body class="guide-layout vs-guide"><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><a class="brand" href="/"><span>Megabonk.org<small>Independent games &amp; guides</small></span></a><nav class="desktop-nav" aria-label="Main navigation">{nav}</nav><details class="mobile-nav"><summary>Menu</summary><nav class="mobile-links" aria-label="Mobile navigation">{nav}</nav></details></div></header><main class="wrap" id="main"><header class="article-head" id="guide"><p class="eyebrow">INDEPENDENT PLAYER GUIDE · VAMPIRE SURVIVORS</p><h1>{h1}</h1><div class="answer">{answer}</div><p class="byline">By Megabonk.org · {'checked 9 November 2026' if route in ['/vampire-survivors/evolutions/','/vampire-survivors/infinite-corridor/','/vampire-survivors/collection-1-0/'] else 'original checks 5 November 2026; progression links updated 9 November'} · Vampire Survivors is by poncle.</p></header><div class="article-layout"><nav class="toc" aria-label="On this page"><strong>On this page</strong>{''.join(f'<a href="#{i}">{h}</a>' for i,h,_ in parts)}</nav><article class="prose">{body}{source}{related}</article></div>{recommendations('vampire-survivors') if recs else ''}</main><footer class="footer"><div class="wrap footer-grid"><div><strong>A guide for your next run.</strong><p>Independent editorial. Not affiliated with poncle or the creators of the games linked here.</p><a href="/#wiki-start">More games &amp; guides →</a></div><nav aria-label="Site information"><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy-policy#vampire-survivors">Privacy</a></nav></div></footer></body></html>'''
 if route in ['/vampire-survivors/'+x+'/' for x in ['sonic-whip','ode-to-castlevania','dlc','unlocks','secret-characters','how-to-beat-death','cherry-bomb-evolution']]:
  html=html.replace('<link rel="stylesheet" href="/assets/pokebonk/site.css">','').replace('/assets/vampire-survivors/site.css','/assets/vampire-survivors/home.css').replace('class="guide-layout vs-guide"','class="guide-layout vs-home"').replace('original checks 5 November 2026; progression links updated 9 November','checked 10 November 2026')
 html=decorate(route,html)
 if route.startswith('/vampire-survivors/'):
  html=html.replace('<a class="brand" href="/"><span>Megabonk.org<small>Independent games &amp; guides</small></span></a>', '<a class="brand" href="/vampire-survivors/"><span>Vampire Survivors<small>Independent player guides</small></span></a>')
 if route=='/vampire-survivors/':
  from vampire_home import redesign
  html=redesign(html)
 return stylesheet(html) if recs else html

def demo_page():
 answer=f'<p><strong>Yes: poncle still hosts a free browser demo on itch.io.</strong> It is the old <strong>v0.2.4 Demo</strong>, not the current commercial game or its online co-op edition. Open it on the author\'s site; this guide explains the first steps and what will not carry over. {ref(1)}</p><p>{ext(DEMO,"poncle on itch.io · open the original demo")}</p>'
 parts=[
 ('demo','Open the original demo',f'<p>Use <strong>poncle.itch.io/vampire-survivors</strong>, then select <strong>Run game</strong>. You are leaving Megabonk.org to play on the author\'s page. We do not embed this page: its response policy allows framing only within its own itch.io context. No game is loaded by reading this guide. {ref(1)}</p><p>Startup checked in desktop Chrome on 5 November 2026: Run game → title → Start → Antonio → Confirm → Start → active battlefield. The client displayed <strong>v0.2.4 - Demo</strong>. Keyboard movement and automatic whip attacks were observed in a short opening check; no complete run or physical-phone test is claimed.</p>'),
 ('start','Start your first run',f'<ol><li>After <strong>Run game</strong>, click inside the game if it is still showing the title artwork. The main menu has a blue <strong>Start</strong> button.</li><li>Choose <strong>Start</strong>. On a fresh profile Antonio is available; the other visible starting portraits may still be locked.</li><li>Choose Antonio, select <strong>Confirm</strong>, then <strong>Start</strong>. In our fresh demo check this entered the grassy battlefield directly.</li><li>Use the arrow keys to move away from the approaching enemies. Attacks fire automatically, so movement and collecting experience are the first jobs.</li></ol><p>The author recommends concentrating levels in two or three offensive weapons instead of spreading upgrades thinly. Experience gems and dropped items do not immediately disappear, so avoid diving into a dangerous crowd just to collect them. These are the author\'s tips, not a promise that one build always wins. {ref(1)}</p><p>If keyboard input does nothing, click inside the game once before pressing an arrow key. The author lists mouse, keyboard, controller and touch support, but this check covered desktop keyboard input only. {ref(1)}</p>'),
 ('editions','Demo or current full game?',table(['You want','Choose','Important difference'],[
 ('A free original browser sample',ext(DEMO,'poncle · itch.io demo'),'Old v0.2.4 demo. The author lists 7 characters, 22 weapons, 12 power-ups and 1 stage across its available content; this is not everything unlocked on a fresh save. '+ref(1)),
 ('Current content and paid DLC',ext(STEAM,'Steam · current commercial edition'),'The full game receives its own updates. The old web demo is not a free current build. Other supported platforms have their own stores. '+ref(2)),
 ('Play online with a friend','<a href="/vampire-survivors/co-op/">Check both devices and stores first</a>','Use the commercial edition. Online compatibility depends on the ecosystem; simply both being on PC is not enough. '+ref(3)),
 ('A different browser survivor','<a href="/games-like-vampire-survivors/">Choose by setup and play style</a>','Pokémon and Warcraft-inspired games are separate projects with separate saves, not DLC for Vampire Survivors.')])+'<p>A page calling itself “Vampire Survivors online” might mean a browser port, a cloud-streaming service or the full game\'s multiplayer. Check the author, host and edition before following its instructions.</p>'),
 ('guides','Full-game progression guides','<p>Choose the task you are working on in the commercial game.</p><ul><li><a href="/vampire-survivors/evolutions/">Weapon evolutions and combo checks</a> — match the passive and diagnose a chest that does not evolve.</li><li><a href="/vampire-survivors/infinite-corridor/">Infinite Corridor</a> — Yellow Sign, both rings and the exact level requirements.</li><li><a href="/vampire-survivors/collection-1-0/">Collection 1.0</a> — identify missing entries for Queen Sigma.</li></ul>'),
 ('game-facts','Full game: genre, dates and Switch 2',f'<p><strong>Vampire Survivors is a time-survival action roguelite:</strong> move through enemy crowds while weapons attack automatically, then choose upgrades as you gain levels. This is the gameplay loop sampled by the old browser demo; it is not a traditional manually aimed shooter. Steam lists <strong>17 December 2021</strong> as Early Access and <strong>20 October 2022</strong> as the full release. Those are Steam dates, not a claim that every console launched that day. {ref(2)}</p><p><strong>Can you use a Switch 2?</strong> Nintendo currently marks the <em>Nintendo Switch version</em> as supported on Switch 2, with behavior consistent with Switch. That compatibility listing alone does not establish a separate native Switch 2 edition, an upgrade price, mouse controls or a measured frame-rate improvement. Check the actual version label before purchasing an upgrade. {ext('https://www.nintendo.com/us/store/products/vampire-survivors-switch/','Nintendo · Switch edition and Switch 2 compatibility')} (checked 9 November 2026).</p><p>If your next step is playing with a friend, use the <a href="/vampire-survivors/co-op/">device and storefront check</a> rather than treating hardware compatibility as crossplay. For modern weapon recipes and unlocks, {ext('https://vampire.survivors.wiki/','Vampire Survivors Wiki')} covers the full game; modern recipe lists do not describe everything available in this older one-stage demo.</p>'),
 ('save','Keep demo progress separate',f'<p>The author\'s itch.io FAQ says the web demo save cannot be transferred to Steam. Do not start a long demo run assuming it will become your full-game save. A login to itch.io is not evidence that the game has cloud-save migration. {ref(1)}</p><p>Use the same original host and browser profile if you return to the demo. Clearing site data or switching browser contexts can affect browser-stored progress; recovery and migration were not tested here. The current commercial game\'s account or cross-save features do not establish compatibility with this older demo.</p>'),
 ('play-together','Looking for multiplayer?',f'<p>The modern full game supports online co-op, but its rules do not apply to this old browser demo. Use our <a href="/vampire-survivors/co-op/">platform and storefront check</a> before buying a second copy or troubleshooting a room code. The developer\'s current FAQ is the authority for supported pairs. {ref(3)}</p>'),
 ('alternatives','Want more browser choices?','<p>For a 3D Pokémon survivor, start with <a href="/pokebonk/play/">PokeBonk</a>. For Warcraft-inspired survival, use <a href="/azeroth-survivors/play/">Aethus’s original-game launch guide</a>. For Diablo-style play, read <a href="/d2-survivors/setup/">D2 Survivors setup</a> first: original and hosted editions have different file requirements. <a href="/games-like-vampire-survivors/">Compare these routes before choosing</a>.</p>')]
 return shell('/vampire-survivors/','Vampire Survivors Browser Demo: Original & Start Guide','Open poncle’s original Vampire Survivors browser demo, follow the first-run steps, and check its content, save limits and full-game differences.','Vampire Survivors browser demo',answer,parts,[(DEMO,'poncle · original itch.io demo','Author content list and save FAQ; original v0.2.4 demo title and fresh Antonio startup checked 5 November 2026. Short opening only, not a full clear or mobile test.'),(STEAM,'Steam · Vampire Survivors','Commercial game identity and store features checked 5 November 2026; distinct from the old HTML5 demo.'),(ONLINE,'poncle · online FAQ','Current online rules checked 5 November 2026; document-based, not a multiplayer session test.')],recs=True)

def coop_page():
 opts=[('steam','Steam on PC'),('ms','Microsoft Store / Game Pass on PC'),('xbox','Xbox Series X|S'),('ps4','PlayStation 4'),('ps5','PlayStation 5'),('switch','Nintendo Switch'),('mobile','Android / iOS'),('demo','Old itch.io browser demo'),('epic','Epic Games Store'),('other','Another / unspecified edition')]
 options='<option value="">Choose a copy…</option>'+''.join(f'<option value="{v}">{l}</option>' for v,l in opts)
 tool=f'<form class="tool" id="pair-form"><div class="tool-grid"><label>Player 1: device and store<select name="player1" required>{options}</select></label><label>Player 2: device and store<select name="player2" required>{options}</select></label></div><button type="submit">Check our copies</button><button type="reset">Clear choices</button><p id="pair-status" role="status" aria-live="polite">Choose two copies to check a documented route.</p><div id="pair-result" class="result" hidden><h3 id="pair-title" tabindex="-1"></h3><p id="pair-text"></p><p>Next: <a href="#start">start a compatible online session</a> or <a href="#local">check shared-screen options</a>. {ext(ONLINE,"poncle · current online FAQ")}</p></div><noscript><p>The interactive check needs JavaScript. Use the compatibility table below for the same documented pairs.</p></noscript></form>'
 parts=[('check','Check your two copies',f'<p>This checks <strong>native online co-op</strong>, not cross-save or screen streaming. Results follow poncle\'s FAQ as checked on 5 November 2026; unlisted store combinations stay unconfirmed. This is a documentation check, not a connection test. Your selections stay on this page and are not saved. {ref(1)}</p>'+tool),
 ('pairs','Documented platform pairs',table(['Two copies','Native online result','Before you start'],[
 ('Steam ↔ Steam','Supported within the same edition','Current commercial game, one device and copy each. '+ref(1)),
 ('Microsoft Store/Game Pass PC ↔ Xbox Series X|S','Supported within the Xbox ecosystem','PC must be the Microsoft edition; Steam on a Windows PC is a different ecosystem. '+ref(1)),
 ('PS4 ↔ PS5','Supported within PlayStation','Each player needs their own game/device and any required online subscription. '+ref(1)),
 ('Switch ↔ Switch','Same-platform online route','Use the current supported console edition and its required online service. '+ref(1)),
 ('Steam ↔ console; Xbox ↔ PlayStation; Switch ↔ other ecosystems','Not supported by the reviewed FAQ','Room codes do not override the ecosystem boundary. '+ref(1)),
 ('Epic ↔ Steam or another unlisted storefront pair','Not confirmed by this guide','The FAQ does not explicitly identify this exact pair. Ask the developer before purchasing for that pairing. '+ref(1)),
 ('Android/iOS ↔ remote players','Mobile excluded at online launch in the FAQ','Do not confuse this with documented local mobile co-op. '+ref(1)+ref(2)),
 ('Old itch.io demo ↔ current game','No native online demo route','The original v0.2.4 browser demo is a separate, older sample. '+ref(3))])),
 ('start','Start a compatible online session',f'<ol><li>Launch the current commercial game on each player\'s own device. First check the two stores above; a code cannot fix incompatible ecosystems.</li><li>Agree on the stage and DLC. The base game is enough for online play; for shared DLC content the FAQ requires every participant to own that pack.</li><li>Choose <strong>Online</strong> from the main menu. One player hosts; the others join using the displayed room code. Xbox also has platform invites. There is no random public matchmaking.</li><li>Choose from your own unlocked characters. The host\'s save controls which stages and items are available.</li><li>When the run finishes, each player chooses whether to apply the group\'s progress to their own save. Check that choice before leaving.</li></ol><p>These steps summarize the developer\'s documentation. We did not run a multiplayer session, check a subscription account or test DLC sharing ourselves. {ref(1)}</p>'),
 ('local','Same room or Remote Play?',f'<p><strong>Local co-op uses a shared screen; native online lets players roam independently.</strong> The current online FAQ says you cannot combine couch and native online players in one session. Every native-online player needs a separate device and game copy. {ref(1)}</p><p>For local PC play, the developer documents one input device per player. If one player uses the keyboard and another a controller, disable <strong>Assign Controller to Player 1</strong> in the options. The image above is the developer\'s local co-op setting, not an Online lobby. {ref(2)}</p><p>On mobile, the local FAQ describes landscape orientation with Bluetooth controllers for additional players. That does not mean phone-to-PC native online is supported. Steam Remote Play Together is another route: it streams a local session, so treat it as shared-screen play with its own input and streaming limitations. It is not proof of native crossplay. {ref(2)}{ref(4)}</p><p class="notice">The older local FAQ still contains launch-era wording that online co-op is unavailable. Use it for local inputs; use the separate current online FAQ for native-online availability and ecosystem rules. {ref(1)}{ref(2)}</p>'),
 ('room-help','When a room code does not work',f'<ol><li>Compare the exact storefronts, not just the operating systems. “We both play on Windows” does not establish compatibility.</li><li>Check that both players selected the native Online mode rather than a shared-screen streaming session.</li><li>Ask the host whether the run has already started. The FAQ says disconnected clients cannot rejoin a run in progress.</li><li>Check the host connection: the FAQ says losing the host ends the session. A client disconnect is treated differently and the remaining players can continue.</li><li>If the documented compatible setup still fails, record both stores, versions and the exact error before contacting {ext('mailto:support@poncle.co.uk','poncle · support email')}. Do not change or delete saves merely to fix a room code.</li></ol><p>These checks separate incompatible setups from issues that need support; they do not promise a fix for every network error. Current rules and disconnect behavior: {ref(1)}</p>')]
 return shell('/vampire-survivors/co-op/','Vampire Survivors Co-op: Crossplay & Storefront Check','Check Vampire Survivors co-op by device and storefront. Compare native online, local play, DLC requirements, room codes and individual progress.','Vampire Survivors co-op: can you play together?',f'<p><strong>Online co-op supports up to four players, but stores and ecosystems matter.</strong> Microsoft Store/Game Pass PC can pair with Xbox Series X|S; PS4 can pair with PS5. Steam-to-console and Xbox-to-PlayStation are outside the supported crossplay ecosystems. Check both copies below before buying or troubleshooting. {ref(1)}</p>',parts,[(ONLINE,'poncle · online FAQ','Primary source for current platform ecosystems, player count, device/copy/DLC requirements, room codes and progress. Checked 5 November 2026; no version stamp or multiplayer test.'),(LOCAL,'poncle · local co-op FAQ','Local input, controller assignment, mobile landscape and Remote Play guidance. Older page retains obsolete no-online launch wording; not used to override the current online FAQ. Official settings image © poncle; screenshot build/date not supplied.'),(DEMO,'poncle · browser demo','Old demo content and version inspected 5 November 2026; not the commercial online edition.'),(STEAM,'Steam · Vampire Survivors','Lists current co-op and Remote Play Together features; checked 5 November 2026.')],script=True)

def compare_page():
 answer='<p><strong>Choose by setup first.</strong> Try the original Vampire Survivors demo for a small no-purchase sample, PokeBonk for a 3D Pokémon survivor, Aethus’s Azeroth Survivors for Warcraft-style classes, or D2 Survivors if you want Diablo-style progression and understand the edition’s file requirements. These are separate games, not interchangeable builds or shared saves.</p>'
 parts=[('choose','Choose a browser survivor',table(['Your priority','Start here','Setup and limits'],[
 ('Original Vampire Survivors, no purchase','<a href="/vampire-survivors/">Official itch.io demo guide</a>','Old v0.2.4, one-stage demo. It is not the modern DLC or online edition. '+ref(1)),
 ('3D movement and Pokémon-themed upgrades','<a href="/pokebonk/play/">PokeBonk browser entry</a>','Our Play page identifies its selected third-party host and captured version. Do not assume that host shares the original account or save. '+ref(2)),
 ('Warcraft-style class choices','<a href="/azeroth-survivors/play/">Azeroth Survivors original launch</a>','Open Aethus’s original site in a new tab. Check WebGPU support and keep saves with their original host. '+ref(3)),
 ('Diablo-style classes and loot','<a href="/d2-survivors/setup/">D2 Survivors edition/setup guide</a>','The original route requires your own compatible Diablo game files; a hosted edition can differ. Check which route you are opening. '+ref(4))])+'<p>This is a setup and play-style comparison, not a tested performance ranking. Earlier game captures retain their dates; every game is not re-tested for a full run today.</p>'),
 ('original-demo','Try the original first',f'<p>If you want to know whether the automatic-attack loop suits you, the author\'s old <a href="/vampire-survivors/">Vampire Survivors browser demo</a> is the most direct sample. Its title displayed v0.2.4 Demo during the short startup check on 5 November 2026. Expect a small older sample, not the present commercial game. The author says its save does not transfer to Steam. {ref(1)}</p><p>{ext(DEMO,'poncle · open original demo in a new tab')}</p><p>If your actual goal is multiplayer with a friend, first use the <a href="/vampire-survivors/co-op/">commercial edition’s compatibility check</a>. A browser demo and an online multiplayer mode answer different questions.</p>'),
 ('pokemon','Pick the Pokémon survivor you mean',f'<p><a href="/pokebonk/">PokeBonk</a> is the 3D survivor choice in this comparison: movement, automatic attacks and run upgrades in a Pokémon-themed setting. Our <a href="/pokebonk/play/">Play entry</a> labels the selected host and its version, so check that label before following an original-game guide. {ref(2)}</p><p><a href="/poke-survivor/">PokéSurvivor</a> is another survivor project with its own host and progress. “Pokémon Vampire Survivors” does not uniquely identify either game. PokéVersus and Poké Arena 2D are competitive arena games; Spires of Azeroth is turn-based card play. Their presence in our wider game recommendations does not make them automatic-attack survivor substitutes.</p><p>Choose by the game shown and the host domain, then keep its own save instructions. Shared character names do not imply account or save compatibility.</p>'),
 ('warcraft','Choose Aethus’s game for Warcraft classes',f'<p><a href="/azeroth-survivors/">Azeroth Survivors</a> uses Warcraft-inspired class and upgrade choices. The original is <strong>wow.aethus.pl</strong>; use our <a href="/azeroth-survivors/play/">original launch guide</a> to check the host, first-load requirements and browser support. It opens the original in a new tab, not a copied client. {ref(3)}</p><p>{ext('https://wow.aethus.pl/','Aethus · original game')}</p><p>Choose this when classes are the draw and you have a usable WebGPU browser/device. Follow the <a href="/azeroth-survivors/beginners-guide/">first-run guide</a> rather than importing expectations from World of Warcraft or an unrelated fan project. Keep existing saves with the host that created them.</p>'),
 ('diablo','Read the D2 setup before pressing Play',f'<p><a href="/d2-survivors/">D2 Survivors</a> is the Diablo II-inspired option. Its original route uses compatible files supplied from your own game installation. Our <a href="/d2-survivors/setup/">setup guide</a> distinguishes the original route from the selected hosted edition, whose file and save behavior can differ. Do not download game-data archives from an unknown third party just to follow a “free browser” headline. {ref(4)}</p><p>{ext('https://d2survivors.lol/','D2 Survivors · original project')}</p><p>Choose it for the class-and-loot setting if that setup suits you; choose the original Vampire Survivors demo instead if you only want a small browser sample without supplying Diablo files. The same host/browser precaution applies when continuing a run.</p>'),
 ('megabonk','Want a 3D commercial alternative?',f'<p>For a downloaded 3D survivor rather than browser play, read our existing <a href="/faq/is-megabonk-worth-it#comparison">Megabonk comparison</a>. It covers the movement and gameplay differences without creating another overlapping comparison page. Buy/no-buy decisions and browser availability are separate tasks. Vampire Survivors already has modern co-op; check the <a href="/vampire-survivors/co-op/">mode and storefront rules</a> rather than assuming the entire genre is single-player. {ref(5)}</p>')]
 return shell('/games-like-vampire-survivors/','Browser Games Like Vampire Survivors: Choose Your Route','Choose browser games like Vampire Survivors by play style and setup. Compare the original demo, PokeBonk, Azeroth Survivors and D2 file requirements.','Browser games like Vampire Survivors',answer,parts,[(DEMO,'poncle · original Vampire Survivors demo','Author description, content and save-transfer boundary; v0.2.4 opening checked 5 November 2026.'),('https://pokebonk.com/','PokeBonk · original game','Original-game identity; our linked Play page separately identifies its selected third-party edition, v0.8.27 captured 26 October 2026. No cross-host migration claim.'),('https://wow.aethus.pl/','Aethus · original Azeroth Survivors','Original browser route and WebGPU/startup boundaries; linked site guides preserve individual version/capture dates. No current full-run benchmark.'),('https://d2survivors.lol/','D2 Survivors · original project','Original route and own-game-file boundary; our setup/Play pages distinguish hosted editions and their separate saves.'),(ONLINE,'poncle · online FAQ','Modern Vampire Survivors online co-op exists; platform and mode restrictions checked 5 November 2026.')])

def build():
 from vampire_progression import pages
 from vampire_batch import pages as batch_pages
 tasks = [('/vampire-survivors/',demo_page()),('/vampire-survivors/co-op/',coop_page()),('/games-like-vampire-survivors/',compare_page())] + pages(shell, ext, table) + batch_pages(shell, ext, table)
 for route,html in tasks:
  f=ROOT/route.strip('/')/'index.html';f.parent.mkdir(parents=True,exist_ok=True);write_html(f,html,encoding='utf-8')
 f=ROOT/'faq/is-megabonk-worth-it.html';s=f.read_text(encoding='utf-8')
 s=s.replace('<section>\n          <h2>How Does It Compare to Vampire Survivors &amp; Other Survivors?</h2>','<section id="comparison">\n          <h2>How Does It Compare to Vampire Survivors &amp; Other Survivors?</h2>')
 s=s.replace('<li>It’s all <strong>single-player only</strong> for now.</li>','<li>The solo survivor loop is a useful comparison, but Vampire Survivors also has local and online co-op. <a href="/vampire-survivors/co-op/">Check its mode and storefront requirements</a> before planning a session with friends. <a href="https://poncle.games/vs-online-faq" target="_blank" rel="noopener noreferrer">poncle · online FAQ ↗</a> (checked 5 November 2026).</li>')
